<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Rendering\Application\Usecase\Render;

use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Rendering\Domain\RenderedAsset;
use Civi\Lughauth\Features\Document\Rendering\Domain\TemplateRenderRequest;
use Civi\Lughauth\Features\Document\Rendering\Domain\Gateway\TemplateRenderGateway;
use Civi\Lughauth\Features\Document\Template\Domain\Template;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateFilter;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateReadGateway;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersion;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionFilter;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionReadGateway;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableFilter;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableReadGateway;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetFilter;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetReadGateway;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

/**
 * Orchestrates the resolution and rendering of a stored template into a document.
 *
 * Responsibilities:
 *   1. Resolve the best-matching Template (tenant-specific first, then global).
 *   2. Select the latest TemplateVersion for that template.
 *   3. Merge tenant-level TemplateVariable defaults with call-site overrides.
 *   4. Load tenant TemplateSnippet records for partial resolution.
 *   5. Delegate the actual string substitution to the TemplateRenderGateway.
 */
class TemplateRenderUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly TemplateReadGateway $templateGateway,
        private readonly TemplateVersionReadGateway $versionGateway,
        private readonly TemplateVariableReadGateway $variableGateway,
        private readonly TemplateSnippetReadGateway $snippetGateway,
        private readonly TemplateRenderGateway $renderGateway,
        private readonly ThemeReadGateway $themeGateway,
    ) {
    }

    /**
     * Render the template identified by input code and channel.
     *
     * Returns null inside the result when no matching template or version exists.
     */
    public function render(TemplateRenderInput $input): TemplateRenderResult
    {
        $this->logDebug("Run Render usecase for Template");
        $span = $this->startSpan("Run Render usecase for Template");
        try {
            $template = $this->resolveTemplate($input->code(), $input->channel(), $input->tenant());
            if (null === $template) {
                $this->logDebug(
                    "No enabled template found: code='{code}' channel='{channel}' tenant='{tenant}'",
                    ['code' => $input->code(), 'channel' => $input->channel()->value, 'tenant' => $input->tenant()?->uid() ?? 'global']
                );
                return new TemplateRenderResult(null);
            }

            $version = $this->latestVersion($template);
            if (null === $version) {
                $this->logDebug("Template '{uid}' has no versions", ['uid' => $template->uid()]);
                return new TemplateRenderResult(null);
            }

            $variables = $this->mergeVariables($input->tenant(), $input->variables());
            $snippets  = $this->loadSnippets($input->tenant());
            $assets    = $this->loadThemeAssets($template);

            $rendered = $this->renderGateway->render(new TemplateRenderRequest(
                htmlContent: $version->getContentHtml(),
                snippets: $snippets,
                variables: $variables,
                outputFormat: $input->outputFormat(),
                subject: $version->getSubject(),
                textContent: $version->getContentText(),
                assets: $assets,
            ));

            return new TemplateRenderResult($rendered);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    // ---------------------------------------------------------------------------
    // Private — domain coordination logic
    // ---------------------------------------------------------------------------

    /**
     * Resolves the best-matching template:
     * tenant-specific (code + channel + tenant) first, then global (code + channel, no tenant).
     */
    private function resolveTemplate(string $code, TemplateChannelOptions $channel, ?TenantRef $tenant): ?Template
    {
        $slide = $this->templateGateway->list((new TemplateFilter())->withCode($code));
        $candidates = $slide->values();

        if (null !== $tenant) {
            foreach ($candidates as $candidate) {
                if (
                    $candidate->getChannel() === $channel
                    && $candidate->isEnabled()
                    && $candidate->getTenant()?->uid() === $tenant->uid()
                ) {
                    return $candidate;
                }
            }
        }

        foreach ($candidates as $candidate) {
            if (
                $candidate->getChannel() === $channel
                && $candidate->isEnabled()
                && null === $candidate->getTenant()
            ) {
                return $candidate;
            }
        }

        return null;
    }

    /** Returns the version with the highest version counter (most recent). */
    private function latestVersion(Template $template): ?TemplateVersion
    {
        $slide    = $this->versionGateway->list((new TemplateVersionFilter())->withTemplate($template));
        $versions = $slide->values();

        if (empty($versions)) {
            return null;
        }

        usort($versions, static fn (TemplateVersion $a, TemplateVersion $b) => ($b->getVersion() ?? 0) <=> ($a->getVersion() ?? 0));

        return $versions[0];
    }

    /**
     * Builds the flat variable map: tenant defaults first, then call-site overrides on top.
     *
     * @param  array<string, string> $overrides
     * @return array<string, string>
     */
    private function mergeVariables(?TenantRef $tenant, array $overrides): array
    {
        $vars = [];

        if (null !== $tenant) {
            $slide = $this->variableGateway->list((new TemplateVariableFilter())->withTenant($tenant));
            foreach ($slide->values() as $variable) {
                if ($variable->isEnabled() && null !== $variable->getValue()) {
                    $vars[$variable->getCode()] = $variable->getValue();
                }
            }
        }

        return array_merge($vars, $overrides);
    }

    /**
     * Loads CSS assets from the theme associated with the template, if any.
     *
     * @return RenderedAsset[]
     */
    private function loadThemeAssets(Template $template): array
    {
        $themeRef = $template->getTheme();
        if (null === $themeRef) {
            return [];
        }

        $theme = $this->themeGateway->resolve($themeRef);
        if (null === $theme || null === $theme->getCustomCss()) {
            return [];
        }

        return [
            new RenderedAsset(
                code: 'theme-css',
                contentType: 'text/css',
                content: $theme->getCustomCss(),
                embedded: false,
            ),
        ];
    }

    /**
     * Loads all enabled snippets for the tenant, indexed by code.
     *
     * @return array<string, string>
     */
    private function loadSnippets(?TenantRef $tenant): array
    {
        if (null === $tenant) {
            return [];
        }

        $snippets = [];
        $slide    = $this->snippetGateway->list((new TemplateSnippetFilter())->withTenant($tenant));
        foreach ($slide->values() as $snippet) {
            if ($snippet->isEnabled()) {
                $snippets[$snippet->getCode()] = $snippet->getContentHtml();
            }
        }

        return $snippets;
    }
}
